stepxmp.pre:
m|mi.note::before {
    content: "[";
    color: #b22222;
}

m|mi.note::after {
    content: "]";
    color: #b22222;
}

m|math.numbered {
    counter-reset: eqnum;
}

m|mtd.eqnum {
    counter-increment: eqnum;
    text-align: right;
}

m|mtd.eqnum::before {
    content: "(" counter(eqnum) ")";
}
